INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('924392d7-14df-48b7-8793-5a2134605bce', NULL, 'system', 'notifications.update', 'notifications', '525b48e4-d742-4b17-b794-13122aa06758', '{"subject":"We received your order {{order_number}}","template":"Hi {{customer_name}}, thanks for your order {{order_number}} ({{total}}). We will confirm it shortly. - {{store_name}}"}', '{"subject":"Order {{ order.name }} received","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Thank you for your order!</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Thank you for your order!</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we have received your order {{ order.name }}. We will call you shortly to confirm it before it ships.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('663efd2c-fd20-4f69-938a-d8d51b074e0d', NULL, 'system', 'notifications.update', 'notifications', '6499763b-4e81-4f38-b8fe-9b557136c877', '{"subject":"Order {{order_number}} confirmed","template":"Your order {{order_number}} is confirmed and being prepared. Total due on delivery: {{cod_amount}}. - {{store_name}}"}', '{"subject":"Order {{ order.name }} confirmed","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is confirmed</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is confirmed</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} is confirmed and we are getting it ready.</p>\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready to pay on delivery.</p>{% endif %}\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('f70a58aa-9f0d-448b-b65a-ed3984ba190c', NULL, 'system', 'notifications.update', 'notifications', 'cfc11688-8cff-49f2-af2b-45896b76c8e1', '{"subject":"Advance payment needed for {{order_number}}","template":"To confirm order {{order_number}}, please pay an advance of {{advance_amount}}. Pay here: {{track_order_url}} - {{store_name}}"}', '{"subject":"Advance payment needed for order {{ order.name }}","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>One more step to confirm your order</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">One more step to confirm your order</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, to confirm order {{ order.name }} please pay an advance of <strong>{{ order.advance_amount | money }}</strong>. The rest is paid on delivery.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Pay the advance</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('526119e4-645b-4621-a412-869753b68184', NULL, 'system', 'notifications.update', 'notifications', '0b5717d8-29c9-41b7-b2a0-b10367704c0f', '{"template":"Your order {{order_number}} has been handed to {{courier_name}}. Tracking: {{tracking_number}} {{tracking_url}} - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} has been handed to {{courier_name}}. Tracking number: {{tracking_number}}. Track it here: {{tracking_url}} anytime.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('b3e8b5f7-7b1b-4e0f-a056-5292e69718dc', NULL, 'system', 'notifications.update', 'notifications', '26d72697-b9e1-4599-a5cc-27337c756eb5', '{"template":"Your order {{order_number}} was delivered. We hope you love it! - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} was delivered. We hope you love it! Reply here if anything is not right.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('3bd6a510-314b-4a0b-940c-85286048db9d', NULL, 'system', 'notifications.update', 'notifications', '48e346b1-844b-4480-bf61-5d4b69538a49', '{"subject":"Order {{order_number}} is on the way","template":"Your order {{order_number}} has been handed to {{courier_name}}. Tracking: {{tracking_number}} {{tracking_url}} - {{store_name}}"}', '{"subject":"Order {{ order.name }} is on the way","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is on the way</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is on the way</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} has been handed to {{ shipment.courier | default: \"the courier\" }}.</p>\n{% if shipment.tracking_number %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Tracking number: <strong>{{ shipment.tracking_number }}</strong></p>{% endif %}\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready to pay on delivery.</p>{% endif %}\n</td></tr>\n{% if shipment.tracking_url or order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ shipment.tracking_url | default: order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Track your parcel</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('1bd83f70-6c77-4763-9280-82eeec39201b', NULL, 'system', 'notifications.update', 'notifications', 'f16cbf38-e941-4c78-be1a-97f1f67d64e0', '{"subject":"Order {{order_number}} delivered","template":"Your order {{order_number}} was delivered. We hope you love it! - {{store_name}}"}', '{"subject":"Order {{ order.name }} delivered","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order was delivered</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order was delivered</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} was delivered. We hope you love it!</p>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">If anything is not right, just reply to this email{% if shop.phone %} or call us at {{ shop.phone }}{% endif %}.</p>\n</td></tr>\n\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('c4e77d04-d15e-415c-a4ef-99ff0c59463c', NULL, 'system', 'notifications.update', 'notifications', 'f71dacef-6f99-482b-8f0f-f0f3aab6cc7a', '{"subject":"Order {{order_number}} cancelled","template":"Your order {{order_number}} has been cancelled. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"subject":"Order {{ order.name }} cancelled","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order was cancelled</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order was cancelled</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} has been cancelled.</p>\n{% if order.paid_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">You paid {{ order.paid_amount | money }} for this order. We will contact you about the refund.</p>{% endif %}\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Questions? Reply to this email{% if shop.phone %} or call us at {{ shop.phone }}{% endif %}.</p>\n</td></tr>\n\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('3a3255b0-7c99-43c1-8c88-f328745326bb', NULL, 'system', 'notifications.update', 'notifications', '9ca84edf-b91c-4f6e-b2d8-392cadd92640', '{"subject":"Return received for {{order_number}}","template":"We have received the return for order {{order_number}}. - {{store_name}}"}', '{"subject":"Return received for order {{ order.name }}","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>We received your return</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">We received your return</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, the returned parcel for order {{ order.name }} has reached us.</p>\n{% if order.paid_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">We will contact you about your payment of {{ order.paid_amount | money }}.</p>{% endif %}\n</td></tr>\n\n\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('9ad531fa-99da-4bae-964a-767db06677e5', NULL, 'system', 'notifications.update', 'notifications', '590fa8b4-3ff4-4b98-9b61-24eeda4503f0', '{"subject":"Pre-order {{order_number}} confirmed","template":"Your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock. - {{store_name}}"}', '{"subject":"Pre-order {{ order.name }} confirmed","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your pre-order is confirmed</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your pre-order is confirmed</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your pre-order {{ order.name }} is confirmed. We will ship it as soon as it arrives in stock.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('c9b28b91-6ef0-4202-bcdc-b41b243cf690', NULL, 'system', 'notifications.update', 'notifications', '0ea91dac-5093-4f88-8010-504fa193646f', '{"template":"Your order {{order_number}} has been cancelled. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} has been cancelled. Questions? Call us at {{store_phone}} or reply here.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('a3593161-ae6e-48f7-94e9-ea8acefcd2f8', NULL, 'system', 'notifications.update', 'notifications', '2d414932-2140-4e5b-8acb-7dbf80bb0f03', '{"template":"We have received the return for order {{order_number}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, the returned parcel for order {{order_number}} has reached us. We will be in touch soon.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('f53d4fcb-2b0c-4e8e-b3a6-4279b99115e3', NULL, 'system', 'notifications.update', 'notifications', '0b67bd71-f67e-4c85-849e-f309b8be1a97', '{"subject":"Order {{order_number}} is out for delivery","template":"Your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready. - {{store_name}}"}', '{"subject":"Order {{ order.name }} is out for delivery","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order arrives today</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order arrives today</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} is out for delivery today{% if shipment.courier %} with {{ shipment.courier }}{% endif %}.</p>\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready for the delivery person.</p>{% endif %}\n</td></tr>\n{% if shipment.tracking_url or order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ shipment.tracking_url | default: order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Track your parcel</a>\n</td></tr>{% endif %}\n\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('80f19549-7126-4560-87ee-76b44e5f4d83', NULL, 'system', 'notifications.update', 'notifications', '9791bf86-a02f-4246-9b36-c17ebb98b9c9', '{"subject":"Order {{order_number}} is being returned","template":"Your order {{order_number}} is being returned to us. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"subject":"Order {{ order.name }} is being returned","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is being returned</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is being returned</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, the parcel for order {{ order.name }} is on its way back to us.</p>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Questions? Reply to this email{% if shop.phone %} or call us at {{ shop.phone }}{% endif %}.</p>\n</td></tr>\n\n\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('9610db46-4a24-47f6-94e9-7726ed94e294', NULL, 'system', 'notifications.update', 'notifications', '713eee90-bcd2-4016-ae99-573b27e352b4', '{"subject":"Payment for {{order_number}} did not go through","template":"Your payment of {{payment_amount}} for order {{order_number}} did not go through. Try again: {{track_order_url}} - {{store_name}}"}', '{"subject":"Payment for order {{ order.name }} did not go through","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your payment didn''t go through</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your payment didn''t go through</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your payment of <strong>{{ payment.amount | money }}</strong> for order {{ order.name }} did not go through. No money was taken. You can try again below.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Try again</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('948b49f4-3453-48cb-b5f9-44f9bcde1d60', NULL, 'system', 'notifications.update', 'notifications', '414ee6d1-46fe-44fc-8e7c-519dbbebb8b2', '{"subject":"Payment received for {{order_number}}","template":"We received {{payment_amount}} for order {{order_number}}. Thank you! - {{store_name}}"}', '{"subject":"Payment received for order {{ order.name }}","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>We received your payment</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">We received your payment</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we received <strong>{{ payment.amount | money }}</strong> for order {{ order.name }}. Thank you!</p>\n{% if order.due_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Still to pay on delivery: <strong>{{ order.due_amount | money }}</strong>.</p>{% endif %}\n</td></tr>\n\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('e50898f6-a2ac-4c8e-ac7f-b17d382844dd', NULL, 'system', 'notifications.update', 'notifications', '4d7f49d0-bf0a-4823-8355-aad259e19927', '{"template":"Hi {{customer_name}}, thanks for your order {{order_number}} ({{total}}). We will confirm it shortly. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, thank you for your order {{order_number}} of {{total}}. We will call you shortly to confirm it.\n\nThank you for shopping with {{store_name}} today."}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('b77890bb-8fc0-4bb3-b1fb-b0261cb24b48', NULL, 'system', 'notifications.update', 'notifications', '8a98a854-8a39-4537-b239-bcb9332315a0', '{"template":"Your order {{order_number}} is confirmed and being prepared. Total due on delivery: {{cod_amount}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} is confirmed and we are getting it ready. Amount to pay on delivery: {{cod_amount}}.\n\nThank you, the {{store_name}} team"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('10f094d8-f903-4ece-86b9-515cd2d1e6a1', NULL, 'system', 'notifications.update', 'notifications', '97fdd4e0-9550-4f32-b296-09a73e6f5337', '{"template":"To confirm order {{order_number}}, please pay an advance of {{advance_amount}}. Pay here: {{track_order_url}} - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, to confirm order {{order_number}} please pay an advance of {{advance_amount}} here: {{track_order_url}} and we will ship it right away.\n\nThank you, the {{store_name}} team"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('5e0ca8eb-abc7-4683-9e26-ff48f47483d3', NULL, 'system', 'notifications.update', 'notifications', 'b379183e-54d1-4c75-9816-06834d9fa38b', '{"template":"Your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock.\n\nThank you, the {{store_name}} team"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('1285911c-de7e-4eb8-86ef-2ce733fa1b8b', NULL, 'system', 'notifications.update', 'notifications', '69146eb2-015d-42fc-9ad6-67a5a445e048', '{"template":"Your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready for the delivery person.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('2fe35189-0d30-494a-bc64-150c3bc411e8', NULL, 'system', 'notifications.update', 'notifications', '9b944802-3698-4830-b346-2b58b754de1d', '{"template":"Your order {{order_number}} is being returned to us. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, the parcel for order {{order_number}} is on its way back to us. Questions? Call us at {{store_phone}} or reply here.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('b925c671-2b0a-44a9-a407-d0b5330590e3', NULL, 'system', 'notifications.update', 'notifications', 'e8b9c98f-7397-4fbe-ab27-0acbcec590d0', '{"template":"Your payment of {{payment_amount}} for order {{order_number}} did not go through. Try again: {{track_order_url}} - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your payment of {{payment_amount}} for order {{order_number}} did not go through. You can try again here: {{track_order_url}} at any time.\n\nThe {{store_name}} team"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('d2d0ceb4-f290-4518-908a-ab2893d52baa', NULL, 'system', 'notifications.update', 'notifications', 'f02fbeda-4211-496d-a2ec-53c20c0fba2d', '{"template":"We received {{payment_amount}} for order {{order_number}}. Thank you! - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, we received your payment of {{payment_amount}} for order {{order_number}}. Thank you!\n\nThe {{store_name}} team"}', '{}', '2026-10-24T08:15:12.962Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('9686f9c2-3dd3-4dcb-b083-5e3f74f679d9', NULL, 'system', 'notifications.update', 'notifications', '525b48e4-d742-4b17-b794-13122aa06758', '{"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Thank you for your order!</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Thank you for your order!</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we have received your order {{ order.name }}. We will call you shortly to confirm it before it ships.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Thank you for your order!</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">{% if order.name %}Order {{ order.name }}{% endif %}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Thank you for your order!</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we have received your order {{ order.name }}.{% if order.reply_url %} Please confirm it below so we can send it quickly.{% else %} We will call you shortly to confirm it before it ships.{% endif %}</p>\n</td></tr>\n{% if order.reply_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.reply_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Confirm your order</a>\n<p style=\"margin:12px 0 0;font-size:13px;line-height:1.6;color:#6b7280;\">Can''t take this order? <a href=\"{{ order.reply_url }}?action=cancel\" style=\"color:#6b7280;\">Cancel it here</a></p>\n</td></tr>{% else %}{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.996Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('f7c085b4-217b-40af-992a-6e380a83b263', NULL, 'system', 'notifications.update', 'notifications', '6499763b-4e81-4f38-b8fe-9b557136c877', '{"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is confirmed</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is confirmed</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} is confirmed and we are getting it ready.</p>\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready to pay on delivery.</p>{% endif %}\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is confirmed</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">{% if order.name %}Order {{ order.name }}{% endif %}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is confirmed</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} is confirmed and we are getting it ready.</p>\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready to pay on delivery.</p>{% endif %}\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-24T08:15:12.996Z', '00000000-0000-4000-8000-000000000001');
